    /// A minimal but structurally complete compatibility dataset document
    /// paired one-to-one with [`document`], so a test can break one thing at
    /// a time on either side.
    fn dataset_document() -> String {
        r#"{
          "format_version": 1,
          "revision": 3,
          "canonical_minecraft_version": "26.2",
          "setting_registry": [
            {"id":"fov","key":"fov","type":"integer","category":"Video","translation_key":"options.fov","manageable":true},
            {"id":"cloudStatus","key":"renderClouds","type":"enum","category":"Video","translation_key":"options.renderClouds","manageable":true},
            {"id":"overrideWidth","key":"overrideWidth","type":"integer","category":"Gameplay","translation_key":null,"manageable":true},
            {"id":"overrideHeight","key":"overrideHeight","type":"integer","category":"Gameplay","translation_key":null,"manageable":true},
            {"id":"resourcePacks","key":"resourcePacks","type":"special","category":"Gameplay","translation_key":null,"manageable":false}
          ],
          "current_canonical_setting_ids": ["fov", "cloudStatus", "overrideWidth", "overrideHeight", "resourcePacks"],
          "representations": [
            {"key":"fov","codec":{"kind":"integer","min":30,"max":110}},
            {"key":"renderClouds","codec":{"kind":"enum_token","tokens":["false","true","fast"],"quoted":true}}
          ],
          "schemas": [{"id":"aaaaaaaaaaaaaaaa","supported":{"fov":0,"cloudStatus":1},"unsupported":[]}],
          "releases": [{"minecraft_version":"26.2","schema":"aaaaaaaaaaaaaaaa"}]
        }"#
        .to_owned()
    }

    /// A catalog that fully accounts for [`dataset_document`]: `fov` and
    /// `cloudStatus` exposed simply, the window fields exposed as one
    /// compound descriptor, and `resourcePacks` explicitly excluded.
    fn document(body: &str) -> String {
        format!(
            r#"{{
              "format_version": 1,
              "canonical_minecraft_version": "26.2",
              "descriptors": [
                {{"id":"fov","category":"video","section":null,"tier":"standard","translation_key":"options.fov","help_translation_key":null,
                  "fields":[{{"role":"value","canonical_id":"fov"}}],
                  "presentation":{{"kind":"integer","default":70,"min":30,"max":110,"step":1}}}},
                {{"id":"cloud_status","category":"video","section":null,"tier":"standard","translation_key":"options.renderClouds","help_translation_key":null,
                  "fields":[{{"role":"value","canonical_id":"cloudStatus"}}],
                  "presentation":{{"kind":"enum","default":"true",
                    "values":[{{"technical_value":"false","enum_constant":"OFF","translation_key":"options.off","ordinal":0}},
                              {{"technical_value":"fast","enum_constant":"FAST","translation_key":"options.clouds.fast","ordinal":1}},
                              {{"technical_value":"true","enum_constant":"FANCY","translation_key":"options.clouds.fancy","ordinal":2}}]}}}},
                {{"id":"window_size","category":"video","section":null,"tier":"standard","translation_key":null,"help_translation_key":null,
                  "fields":[{{"role":"width","canonical_id":"overrideWidth"}},{{"role":"height","canonical_id":"overrideHeight"}}],
                  "presentation":{{"kind":"window_size"}}}}
                {body}
              ],
              "exclusions": [{{"canonical_id":"resourcePacks","reason":"resource-pack selection belongs to resource/pack management"}}]
            }}"#
        )
    }

    fn dataset() -> OptionsDataset {
        OptionsDataset::parse(&dataset_document()).expect("valid")
    }

