    #[test]
    fn the_bundled_catalogs_accounting_agrees_with_the_bundled_dataset() {
        let catalog = MinecraftPreferenceCatalog::bundled().expect("valid");
        let dataset = OptionsDataset::bundled();

        let exposed: BTreeSet<&str> = catalog
            .descriptors
            .iter()
            .flat_map(MinecraftPreferenceDescriptor::canonical_ids)
            .collect();
        let excluded: BTreeSet<&str> = catalog
            .exclusions
            .iter()
            .map(|exclusion| exclusion.canonical_id.as_str())
            .collect();
        let current: BTreeSet<&str> = dataset
            .current_canonical_setting_ids
            .iter()
            .map(String::as_str)
            .collect();

        assert!(exposed.is_disjoint(&excluded));
        let accounted: BTreeSet<&str> = exposed.union(&excluded).copied().collect();
        assert_eq!(accounted, current);
    }

