    #[test]
    fn a_key_binding_default_distinguishes_bound_unbound_and_unproven() {
        let bound: PreferencePresentation = serde_json::from_str(
            r#"{"kind":"key_binding","default":{"serialized":"key.keyboard.w","unbound":false}}"#,
        )
        .expect("valid");
        assert_eq!(
            bound,
            PreferencePresentation::KeyBinding {
                default: Some(KeyBindingDefaultPresentation {
                    serialized: Some("key.keyboard.w".to_owned()),
                    unbound: false,
                })
            }
        );

        let unbound: PreferencePresentation = serde_json::from_str(
            r#"{"kind":"key_binding","default":{"serialized":"key.keyboard.unknown","unbound":true}}"#,
        )
        .expect("valid");
        assert_eq!(
            unbound,
            PreferencePresentation::KeyBinding {
                default: Some(KeyBindingDefaultPresentation {
                    serialized: Some("key.keyboard.unknown".to_owned()),
                    unbound: true,
                })
            }
        );

        // No default proven at all - must not be confused with a proven
        // bound-to-nothing or proven-unbound default.
        let unproven: PreferencePresentation =
            serde_json::from_str(r#"{"kind":"key_binding","default":null}"#).expect("valid");
        assert_eq!(
            unproven,
            PreferencePresentation::KeyBinding { default: None }
        );
    }

