    #[test]
    fn structurally_broken_documents_are_refused_before_touching_any_dataset() {
        let cases = [
            (
                "two descriptors sharing one id",
                document("").replace("\"id\":\"cloud_status\"", "\"id\":\"fov\""),
            ),
            (
                "a window size descriptor missing its height field",
                document("").replace(
                    r#""fields":[{"role":"width","canonical_id":"overrideWidth"},{"role":"height","canonical_id":"overrideHeight"}]"#,
                    r#""fields":[{"role":"width","canonical_id":"overrideWidth"}]"#,
                ),
            ),
            (
                "an enum default absent from its own values",
                document("").replace("\"default\":\"true\"", "\"default\":\"not-a-real-value\""),
            ),
            (
                "an inverted numeric domain",
                document("").replace(
                    r#""min":30,"max":110"#,
                    r#""min":200,"max":110"#,
                ),
            ),
            (
                "a numeric default outside its own domain",
                document("").replace(r#""default":70,"min":30"#, r#""default":9999,"min":30"#),
            ),
            (
                "an exclusion with no reason",
                document("").replace(
                    "\"reason\":\"resource-pack selection belongs to resource/pack management\"",
                    "\"reason\":\"   \"",
                ),
            ),
        ];
        for (why, json) in cases {
            assert!(
                matches!(
                    MinecraftPreferenceCatalog::parse(&json),
                    Err(CatalogError::Inconsistent { .. })
                ),
                "{why} must be refused"
            );
        }
    }

